}

G["forever/alliance/05-duskwood"] = {
	["/lay down beside {npc:7207}"] = "在{npc:7207}旁边 /lay down",
	["Back to the {area:69} gryphon master: fly to {area:42} for {zone:1431}'s second loop."] = "返回 {area:69} 的狮鹫管理员处，飞往 {area:42}，进行 {zone:1431} 的第二轮路线。",
	["Back to {area:42}"] = "回到{area:42}",
	["Carrion Recluses lurk in the woods on the way west, and Venom Web Spiders, Pygmy Venom Web Spiders and Green Recluses crawl just south of {npc:311}'s camp: each can drop a leg."] = "食腐独行蛛潜伏在西行路上的树林里，结网毒蜘蛛、小型结网毒蜘蛛和绿色独行蛛在{npc:311}营地南边爬行：每种都可能掉蜘蛛腿。",
	["Cathedral of Light"] = "光明大教堂",
	["Class trainer"] = "职业训练师",
	["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "继续向西到{area:94}。{object:673515}在道路南边的废弃房屋旁发光。",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}北半部的所有食尸鬼都可能掉落肋骨：{npc:3}和{npc:210}（24-27级）比较好打；{npc:604}和{npc:570}（27-29级）也会掉。精英{npc:522}在墓间游荡：远离他。\n小心：{npc:948}死亡时会施放{spell:3428}，召来额外的敌人。",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds.\nCareful: {npc:503} (31) and {npc:771} (32), both rares, haunt the cemetery's north and west, and {npc:1200} (32, elite) keeps to the house at its western edge: leave them be."] = "{area:492}北半部的每种食尸鬼都可能掉落肋骨：食肉者和嚼骨者（24-27级）较好杀；瘟疫传播者和食脑者（27-29级）也会掉。精英{npc:522}在墓地里游荡：离他远点。\n小心：{npc:948}死亡时会施放{spell:3428}，会额外招来增援。\n小心：{npc:503}（31级）和{npc:771}（32级）都是稀有，出没在墓地北侧和西侧；{npc:1200}（32级，精英）守在墓地西缘的屋子里：都别惹。",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}北半部的所有食尸鬼均有几率掉落肋骨，包括食腐者、噬骨者、瘟疫食尸鬼和食脑者。\n注意：{npc:948}死亡时会施放{spell:3428}，召来额外的敌人。",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿道路向西北经过墓地，前往森林最西缘的{npc:311}营地。{npc:893}站在{npc:311}旁边。",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest."] = "从{area:1002}沿路向南进入{area:10}；{area:42}在森林东侧。",
	["For {npc:1212} in {zone:1453}'s Cathedral, on the walk north"] = "交给{zone:1453}大教堂的{npc:1212}，往北走时",
	["For {npc:1217} in {area:150} (the {zone:1437} guide)"] = "交给{area:150}的{npc:1217}（见{zone:1437}指南）",
	["For {npc:288}, at {area:94} on the way west"] = "给{npc:288}：在西行路上的{area:94}",
	["From level 28: the Skeletal Raiders, Healers and Warders stand in the west part of the {area:492}, just east of {npc:311}'s camp.\nCareful: The Warders are 28-29 and the skeletons stand close together: pull one at a time.\nCareful: {npc:522}, an elite (35), wanders these graves too, and {npc:771} (32, rare) haunts the west part: keep away from both."] = "28级起：骷髅袭击者、治疗者和守卫站在{area:492}西半部，就在{npc:311}营地以东。\n小心：守卫是28-29级，骷髅站得很密：一次拉一只。\n小心：精英{npc:522}（35级）也在这些坟墓间游荡，{npc:771}（32级，稀有）出没在西半部：两者都远离。",
	["Ghoul Ribs"] = "食尸鬼的肋骨",
	["Gooey Spider Legs"] = "粘糊的蜘蛛腿",
	["Head back east along the road to the {area:245}."] = "沿路向东回到{area:245}。",
	["Head back east to {area:42}."] = "向东回到{area:42}。",
	["Head north through Elwynn to {area:1519}; Mathias Shaw is at SI:7 in {object:2100}."] = "向北穿过艾尔文森林前往{area:1519}；马迪亚斯·肖恩在{object:2100}的军情七处。",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "向北穿过艾尔文森林前往{zone:1453}；马迪亚斯·肖尔位于{object:2100}的军情七处。",
	["Head south through the cemetery towards {area:94}. Skeletal Fiends and Skeletal Horrors walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "穿过墓地向南前往{area:94}。骸骨魔和恐怖骸骨在墓地南半部游荡。精英{npc:522}在墓地间徘徊：离他远点。",
	["Head west along the road once more."] = "再次沿路向西走。",
	["Head west along the road out of {area:94} into {area:40}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "沿路向西离开{area:94}进入{area:40}。{npc:7024}在边界内侧的山丘上监视{npc:7053}的塔楼。守卫塔楼的{npc:7051}（23级）身上带着钥匙；克拉文的手记在塔顶的箱子里。",
	["Head west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "从{area:94}沿路向西进入{zone:1436}。{npc:7024}在刚过边界的山丘上监视{npc:7053}的高塔。守塔的{npc:7051}（23 级）携带钥匙，克拉文·摩特维克的日记在塔顶箱子里。",
	["Head west to the hermit once more."] = "再次向西去找隐士。",
	["Hearth back to {area:42} if you bound at the Scarlet Raven Tavern on the first loop, or head back east along the road."] = "若第一圈时把炉石绑在了血鸦旅店，就炉石回{area:42}；不然就沿大路往东走回去。",
	["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "她的房子在{area:42}东南方的山上，{area:121}上方。",
	["Inside"] = "在里面",
	["Level 22 and 24 spells"] = "22级和24级法术",
	["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "接下来：学习技能，再从 {zone:1453} 飞往 {area:150}，前往 {zone:1437}。",
	["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "下一步：去{zone:1453}训练，然后从{area:17203}乘船前往{area:442}，再去{zone:1440}。",
	["Nightbane Shadow Weaver"] = "夜行魔织影者",
	["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里出售，存货有限；{area:150}的{npc:1448}也卖。\n{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["North from {area:94} through Elwynn: {area:87} is on the road to {zone:1453}."] = "从 {area:94} 向北穿过艾尔文森林：去 {zone:1453} 的路上会经过 {area:87}。",
	["North into {area:42}: {npc:276}'s house stands at the east end of town, on the way in."] = "向北进入{area:42}：{npc:276}的房子在镇子东端，进镇路上就能看到。",
	["On into {zone:1453}: {npc:1212} stands in the Cathedral of Light, on the way to the gryphon master. His next quest is for {npc:1217} in {area:150}, where the flight lands."] = "继续进入{zone:1453}：{npc:1212}站在圣光大教堂，就在去狮鹫管理员的路上。他的下一个任务要交给{area:150}的{npc:1217}，那里也是飞行落点。",
	["On into {zone:1453}: {npc:297} (the arrow shows him) takes the letter; the {object:1561} beside him holds the next clue."] = "继续进入{zone:1453}：{npc:297}（箭头会指他）收下信；他旁边的{object:1561}里有下一条线索。",
	["On into {zone:1453}: {npc:6173} and {npc:6171} are in the Cathedral of Light, on the way to the gryphon master."] = "继续前往 {zone:1453}：{npc:6173} 和 {npc:6171} 在圣光大教堂，去狮鹫管理员处时顺路经过。",
	["On the way west to {npc:311}: Skeletal Fiends and Skeletal Horrors walk the cemetery's southern half, north of {area:94}. {npc:522}, an elite, wanders the graves: keep away from him."] = "往西去{npc:311}的路上：骷髅恶鬼和骷髅恐魔在墓地南半部、{area:94}以北走动。精英{npc:522}在坟墓间游荡：离他远点。",
	["Pygmy Venom Web Spider"] = "小毒网蜘蛛",
	["Rabid Dire Wolf"] = "狂躁凶狼",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {area:40} border, so you can easily pull several mobs at once."] = "狂躁凶狼在墓地和{npc:289}周围的森林游荡，饥饿凶狼在他东北的山丘。小毒网蜘蛛在墓地东边爬行，掉落毒液。墓地北半部的每个食尸鬼都可能掉落獠牙。\n小心：狼和其他种类的蜘蛛共处{area:40}边界一带，很容易一次拉好几只怪。",
	["Rogue training"] = "学习潜行者技能",
	["Rot Blossoms"] = "{item:1598}",
	["Shaman training"] = "萨满祭司训练",
	["Skeletal Fiend"] = "骷髅恶鬼",
	["Skeletal Horror"] = "骷髅恐魔",
	["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "{npc:202}在{area:42}与{area:121}之间、镇子东南方的山坡上游荡；它们掉落{item:1598}。",
	["Skeletal Mage"] = "骷髅法师",
	["Skeletal Raiders"] = "骷髅袭击者",
	["Skeletal Warrior"] = "骷髅战士",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {area:10} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "骷髅战士和骷髅法师在{area:42}东南的坟墓间走动，位于山上{npc:302}的房子下方。{area:10}里的每个骷髅都可能掉落{item:2378}。\n小心：骷髅彼此站得很近，直接冲进去往往会一次拉好几只。",
	["Starving Dire Wolf"] = "饥饿凶狼",
	["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地位于村子北边。恐怖骸骨和骸骨魔在墓地南半部游荡。精英{npc:522}在墓地间徘徊：离他远点。",
	["The hermit's shack stands in the woods north-east of the {area:492}."] = "隐士的小屋在{area:492}东北方的树林里。",
	["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "松土堆在农舍南边的老树桩旁。",
	["The {npc:511} (26) hides in the small crypt by the {area:121}, south of {area:42}; the glass is inside."] = "{npc:511}（26级）藏在{area:42}以南、{area:121}旁的小墓穴里；玻璃就在里面。",
	["Train here, in {zone:1453}, before you go on."] = "继续出发前，先在{zone:1453}学习技能。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Your new spells"] = "你的新法术",
	["{area:108} flight master"] = "{area:108}飞行管理员",
	["{area:1097}: kill these as you meet them"] = "{area:1097}：遇到就杀",
	["{area:121}: kill these as you meet them"] = "{area:121}：遇到就杀",
	["{area:492}: kill these as you meet them"] = "{area:492}：沿途击杀以下目标",
	["{area:69} flight master"] = "{area:69} 飞行管理员",
	["{item:1946}: the {npc:511} in the cemetery's crypt is level 26; it waits for the {zone:1431} return"] = "{item:1946}：墓地地穴里的{npc:511}是26级；留到回到{zone:1431}时再做",
	["{item:1946}: the {npc:511}, in the crypt of the cemetery just below"] = "{item:1946}：{npc:511}，就在下方墓园的墓穴里",
	["{item:1946}; inside"] = "{item:1946}：在屋内",
	["{item:281046}, from the {object:673515}"] = "{item:281046}，来自{object:673515}",
